import{_ as d,o as e,c as r,a2 as p}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Time-and-Date-Formats.md","filePath":"manual-zh/Time-and-Date-Formats.md","lastUpdated":1785684581000}'),a={name:"manual-zh/Time-and-Date-Formats.md"};function o(m,t,y,T,E,c){return e(),r("div",null,[...t[0]||(t[0]=[p('<h4 id="_6-7-4-5-时间与日期格式" tabindex="-1">6.7.4.5 时间与日期格式 <a class="header-anchor" href="#_6-7-4-5-时间与日期格式" aria-label="Permalink to &quot;6.7.4.5 时间与日期格式&quot;">​</a></h4><p>在 PSPP 中，<em>时间</em> 是一个间隔。时间格式在易于理解的时间间隔描述与 PSPP 对时间间隔的内部表示（即间隔所含的秒数）之间进行转换。PSPP 有三种时间格式：</p><table tabindex="0"><thead><tr><th>时间格式</th><th>模板</th><th>示例</th></tr></thead><tbody><tr><td>MTIME</td><td>MM:SS.ss</td><td>91:17.01</td></tr><tr><td>TIME</td><td>hh:MM:SS.ss</td><td>01:31:17.01</td></tr><tr><td>DTIME</td><td>DD HH:MM:SS.ss</td><td>00 04:31:17.01</td></tr></tbody></table><p><em>日期</em> 是过去或未来某一时刻。在内部，PSPP 将日期表示为自 <em>纪元</em> （1582 年 10 月 14 日午夜）起经过的秒数。日期格式在可读日期与 PSPP 对日期和时间的数值表示之间进行转换。PSPP 有多种日期格式：</p><table tabindex="0"><thead><tr><th>日期格式</th><th>模板</th><th>示例</th></tr></thead><tbody><tr><td>DATE</td><td>dd-mmm-yyyy</td><td>01-OCT-1978</td></tr><tr><td>ADATE</td><td>mm/dd/yyyy</td><td>10/01/1978</td></tr><tr><td>EDATE</td><td>dd.mm.yyyy</td><td>01.10.1978</td></tr><tr><td>JDATE</td><td>yyyyjjj</td><td>1978274</td></tr><tr><td>SDATE</td><td>yyyy/mm/dd</td><td>1978/10/01</td></tr><tr><td>QYR</td><td>q Q yyyy</td><td>3 Q 1978</td></tr><tr><td>MOYR</td><td>mmm yyyy</td><td>OCT 1978</td></tr><tr><td>WKYR</td><td>ww WK yyyy</td><td>40 WK 1978</td></tr><tr><td>DATETIME</td><td>dd-mmm-yyyy HH:MM:SS.ss</td><td>01-OCT-1978 04:31:17.01</td></tr><tr><td>YMDHMS</td><td>yyyy-mm-dd HH:MM:SS.ss</td><td>1978-01-OCT 04:31:17.01</td></tr></tbody></table><p>前面表格中的模板描述了时间与日期格式如何被输入与输出：</p><p><code>dd</code></p><p>月份中的日期，从 1 到 31。输出时始终为两位数字。</p><p><code>mm</code><code>mmm</code></p><p>月份。输出时，<code>mm</code> 为两位数字，<code>mmm</code> 为英文月份名的前三个字母（January、February……）。输入时，这两种格式以及罗马数字均可接受。</p><p><code>yyyy</code></p><p>年份。输出时，DATETIME 和 YMDHMS 始终产生 4 位年份；其他格式可产生 2 位或 4 位年份。2 位年份所假定的世纪取决于 EPOCH 设置（见 <a href="./SET#SET-EPOCH">SET EPOCH</a>）。输出时，超出纪元的年份会导致整个字段用星号（‘*’）填充。</p><p><code>jjj</code></p><p>年中的天数（儒略日），从 1 到 366。这恰好是三位数字，表示自年初起经过的天数。1 月 1 日被视为第 1 天。</p><p><code>q</code></p><p>年中的季度，从 1 到 4。季度始于 1 月 1 日、4 月 1 日、7 月 1 日和 10 月 1 日。</p><p><code>ww</code></p><p>年中的周数，从 1 到 53。输出时恰好为两位数字。1 月 1 日是第 1 周的第一天。</p><p><code>DD</code></p><p>天数计数，可为正数或负数。输出时至少为两位数字。</p><p><code>hh</code></p><p>小时计数，可为正数或负数。输出时至少为两位数字。</p><p><code>HH</code></p><p>一天中的小时，从 0 到 23。输出时恰好为两位数字。</p><p><code>MM</code></p><p>在 MTIME 中，为分钟计数，可为正数或负数。输出时至少为两位数字。</p><p>在其他格式中，为小时中的分钟，从 0 到 59。输出时恰好为两位数字。</p><p><code>SS.ss</code></p><p>分钟中的秒，从 0 到 59。整数部分输出时恰好为两位数字。输出时，秒与小数部分可能包含也可能不包含，取决于字段宽度与小数位数。输入时，秒与小数部分可选。DECIMAL 设置控制作为小数点接受并显示的小数点字符（见 <a href="./SET#SET-DECIMAL">SET DECIMAL</a>）。</p><p>输出时，日期与时间格式使用表中所示的定界符。输入时，日期各组成部分可由空格或字符 ‘-’、‘/’、‘.’、‘,’ 之一分隔，时间各组成部分可由空格或 ‘:’ 分隔。输入时，分隔季度与年份的 ‘Q’ 以及分隔周与年份的 ‘WK’ 可以大写或小写，其周围的空格可选。</p><p>输入时，所有时间与日期格式都接受任意数量的头部与尾部空白。</p><p>时间与日期格式的最大宽度为 40 列。每种时间与日期格式的最小输入与输出宽度如下所示：</p><table tabindex="0"><thead><tr><th>格式</th><th>最小输入宽度</th><th>最小输出宽度</th><th>选项</th></tr></thead><tbody><tr><td>DATE</td><td>8</td><td>9</td><td>4 位年份</td></tr><tr><td>ADATE</td><td>8</td><td>8</td><td>4 位年份</td></tr><tr><td>EDATE</td><td>8</td><td>8</td><td>4 位年份</td></tr><tr><td>JDATE</td><td>5</td><td>5</td><td>4 位年份</td></tr><tr><td>SDATE</td><td>8</td><td>8</td><td>4 位年份</td></tr><tr><td>QYR</td><td>4</td><td>6</td><td>4 位年份</td></tr><tr><td>MOYR</td><td>6</td><td>6</td><td>4 位年份</td></tr><tr><td>WKYR</td><td>6</td><td>8</td><td>4 位年份</td></tr><tr><td>DATETIME</td><td>17</td><td>17</td><td>秒</td></tr><tr><td>YMDHMS</td><td>12</td><td>16</td><td>秒</td></tr><tr><td>MTIME</td><td>4</td><td>5</td><td></td></tr><tr><td>TIME</td><td>5</td><td>5</td><td>秒</td></tr><tr><td>DTIME</td><td>8</td><td>8</td><td>秒</td></tr></tbody></table><p>表中，“选项”描述了增大输出宽度所能启用的事项：</p><p>4 位年份</p><p>比最小宽度宽 2 列的字段会包含 4 位年份。（DATETIME 和 YMDHMS 格式始终包含 4 位年份。）</p><p>秒</p><p>比最小宽度宽 3 列的字段会同时包含秒与分钟。比最小宽度宽 5 列或更宽的字段，还可以包含小数点与小数秒（但不超过格式小数位数所允许的数量）。</p><p>对于时间与日期格式，默认输出格式与输入格式相同，但如有必要，PSPP 会将字段宽度增大到输出所允许的最小值。</p><p>窄于字段宽度的时间或日期在字段内右对齐。</p><p>当时间或日期超出字段宽度时，会从末尾截去字符，直到能够容纳。这可能出现在不常见的情况下，例如年份大于 9999（会多出一个数字），或对 MTIME、TIME、DTIME 上的负值（会添加一个前导负号）。</p><p>系统缺失值输出为字段右端的一个句点。</p>',42)])])}const s=d(a,[["render",o]]);export{h as __pageData,s as default};
